    return ($a % $mod + $mod) % $mod;
}

function modinv($a, $mod) {
    return pow($a, $mod - 2, $mod);
}

$ans = 0;

for ($k = 1; $k <= $n; ++$k) {
    // Compute C(n, k) mod p
    $comb = 1;
    for ($i = 1; $i <= $k; ++$i) {
        $comb = mod($comb * ($n - $k + $i), $p);
        $comb = mod($comb * modinv($i, $p), $p);
    }

    // Compute k^m mod p
    $pow_km = 1;
    for ($i = 0; $i < $m; ++$i) {
        $pow_km = mod($pow_km * $k, $p);
    }

    // Compute 2^m mod p
    $pow_2m = 1;
    for ($i = 0; $i < $m; ++$i) {
        $pow_2m = mod($pow_2m * 2, $p);
    }

    // Compute (n - k)^m mod p
    $pow_nk = 1;
    for ($i = 0; $i < $m; ++$i) {
        $pow_nk = mod($pow_nk * ($n - $k), $p);
    }

    // Compute term = C(n, k) * k^m * 2^m mod p
    $term = mod($comb * $pow_km, $p);
    $term = mod($term * $pow_2m, $p);

    // Compute subtract = C(n, k) * (n - k)^m * 2^m mod p
    $subtract = mod($comb * $pow_nk, $p);
    $subtract = mod($subtract * $pow_2m, $p);

    // Update ans
    $ans = mod($ans + $term, $p);
    $ans = mod($ans - $subtract, $p);
}

echo $ans . "\n";
